--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-11-04 08:18:56.446064755 +0000
@@ -0,0 +1,72 @@
+import type { SessionEvent } from '../types.ts';
+
+// Shortcuts that make a change look finished without being finished. A finding names what was seen; the
+// model decides whether the shortcut was right, so the check reminds and never refuses.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(m?[jt]sx?|py|go|rs|rb|java|kt|cs|cc|cpp|c|h|hpp|swift|php)$/;
+const TEST = /(^|\/)(tests?|__tests__)\/|\.(test|spec)\.[jt]sx?$|_test\.(go|py)$|(^|\/)test_[^/]*\.py$/;
+
+// Line rules apply to added lines of code files; `test` rules apply to test files only.
+const LINE_RULES: { rule: string; pattern: RegExp; test?: boolean }[] = [
+  { rule: 'suppression', pattern: /@ts-(ignore|nocheck)|eslint-disable|# ?type: ?ignore|# ?noqa|# ?pylint: ?disable|\/\/ ?nolint|biome-ignore/ },
+  { rule: 'swallowed-error', pattern: /catch\s*(\([^)]*\))?\s*\{\s*\}|^except\b[^:]*:\s*pass$/ },
+  { rule: 'type-escape', pattern: /\bas any\b/ },
+  { rule: 'stub', pattern: /throw new Error\(\s*['"`]not implemented['"`]|NotImplementedError|\btodo!\(|\bunimplemented!\(/i },
+  { rule: 'test-skipped', pattern: /\.skip\(|\bx(it|describe|test)\(|\bt\.Skip(Now|f)?\(|pytest\.mark\.skip|@unittest\.skip/, test: true },
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  return changes.flatMap((c) => {
+    const test = TEST.test(c.path);
+    if (c.deleted) return test ? [{ rule: 'test-deleted', path: c.path }] : [];
+    const out: Finding[] = [];
+    if (test && c.removed.length > c.added.length) out.push({ rule: 'test-weakened', path: c.path });
+    if (!CODE.test(c.path)) return out;
+    for (const line of c.added) {
+      const text = line.trim();
+      for (const r of LINE_RULES) if (r.pattern.test(text) && (!r.test || test)) out.push({ rule: r.rule, path: c.path, line: text });
+    }
+    return out;
+  });
+}
+
+export const describeFinding = (f: Finding) => (f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
+
+export const slopReminder = (flags: string[]) =>
+  `cedia's slop check found shortcuts in this run's changes:\n${flags.map((f) => `- ${f}`).join('\n')}\nFix each one. If a shortcut is right, say why in your report, then report.`;
+
+// Parses a `git diff -p -U0` patch into per-file changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const file = /^diff --git a\/.+ b\/(.+)$/.exec(line);
+    if (file) {
+      cur = { path: file[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, the changes are what completed edit and write calls say they made.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const completed = new Set(events.flatMap((e) => (e.kind === 'tool_result' && e.status === 'completed' ? [e.callId] : [])));
+  const lines = (s: unknown) => String(s ?? '').split('\n');
+  return events.flatMap((e): FileChange[] => {
+    if (e.kind !== 'tool_intent' || !completed.has(e.callId)) return [];
+    const path = String(e.input.path);
+    if (e.tool === 'write') return [{ path, added: lines(e.input.content), removed: [], deleted: false }];
+    if (e.tool !== 'edit') return [];
+    const edits = Array.isArray(e.input.edits) ? (e.input.edits as { old_text?: unknown; new_text?: unknown }[]) : [];
+    return [{ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false }];
+  });
+}
