+import type { Snapshots } from '../safety/snapshot.ts';
+import type { EventOf, SessionEvent } from '../types.ts';
+
+// The slop guard looks at what a run changed for shortcuts that make work look done. It reads the change, not the model's words.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: SlopRule; path: string; line?: string };
+
+const CODE = /\.(m?[jt]sx?|c?jsx?|py|go|rs|java|kt|rb|php|cs|swift|c|cc|cpp|h|hpp|sh)$/;
+const TEST = /(^|\/)(tests?|__tests__)\/|[._]tests?\.[a-z]+$|[._]spec\.[a-z]+$|(^|\/)test_[^/]*$/;
+const ASSERT = /\bexpect\(|\bassert/;
+const SKIP = /\.skip\(|\bxit\(|\bxdescribe\(|\bt\.Skip\(|@pytest\.mark\.skip|\bpytest\.skip\(|\bself\.skipTest\(|#\[ignore\]/;
+const LINE_RULES: [SlopRule, RegExp][] = [
+  ['suppression', /@ts-ignore|@ts-expect-error|eslint-disable|# type: ignore|# noqa\b|# pylint: disable|\/\/ nolint|#\[allow\(/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|except[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|:\s*any\b|<any>/],
+  ['stub', /not implemented|NotImplementedError|unimplemented!|todo!\(/i],
+];
+
+// Reads a `git diff -U0` patch: the hunk lines are the change, so a removed line that starts with `--` still counts.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const header = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (header) {
+      cur = { path: header[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+    else if (!inHunk && line.startsWith('deleted file mode')) cur.deleted = true;
+  }
+  return out;
+}
+
+// The run's changes: the snapshot diff from its first tree to its last when snapshots ran (bash included),
+// else the completed edit and write calls.
+export function changesOf(events: SessionEvent[], snapshots?: Snapshots): FileChange[] {
+  const trees = events.flatMap((e) => (e.kind === 'snapshot' ? [e.tree] : []));
+  if (trees.length) return snapshots ? changesFromPatch(snapshots.patch(trees[0]!, trees.at(-1)!)) : [];
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  const lines = (s: unknown) => String(s ?? '').split('\n');
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent) continue;
+    const path = String(intent.input.path ?? '');
+    if (intent.tool === 'write') out.push({ path, added: lines(intent.input.content), removed: [], deleted: false });
+    else if (intent.tool === 'edit') {
+      const edits = (intent.input.edits as { old_text?: unknown; new_text?: unknown }[] | undefined) ?? [];
+      out.push({ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false });
+    }
+  }
+  return out;
+}
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const isTest = TEST.test(c.path);
+    if (isTest && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (isTest && !c.deleted && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
