@@ -0,0 +1,37 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('10 units of one SKU get 5% off the line', () => {
+    // 10 mugs = 4500; 5% = 225 off -> 4275 < 5000, shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('50 units of one SKU get 10% off the line', () => {
+    // 50 pens = 6000; 10% = 600 off; 5400 >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('units of the same SKU are merged before the bulk tier is chosen', () => {
+    // 6 + 4 mugs = 10 units -> 5% tier, same as one line of 10
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 4]]))).toMatchObject({ subtotal: 4275, tax: 355, total: 5430 });
+  });
+
+  test('shipping threshold is checked after the coupon', () => {
+    // 2 tees + 1 bag = 5200 >= 5000 before the coupon; SAVE10 takes 520 -> 4680 < 5000, so shipping 800
+    // tax 7% of 5480 = 383.6 -> 384; total 4680 + 800 + 384 = 5864
+    expect(totals(cart('US', [['TEE', 2], ['BAG', 1]], 'SAVE10'))).toMatchObject({ coupon: 520, shipping: 800, tax: 384, total: 5864 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+
+  test('UK order just under 4000 pays shipping', () => {
+    // 1 tee = 1500 + 1 cap = 1200 -> 2700 < 4000; shipping 700; tax 20% of 3400 = 680
+    expect(totals(cart('UK', [['TEE', 1], ['CAP', 1]]))).toMatchObject({ shipping: 700, tax: 680, total: 4080 });
+  });
+});

