+import { expect, test } from 'bun:test';
+import { LRU, type EvictReason } from '../src/lru.ts';
+
+function setup(capacity: number, ttl: number) {
+  let t = 0;
+  const cache = new LRU<string, number>(capacity, ttl, () => t);
+  const evicted: [string, number, EvictReason][] = [];
+  cache.onEvict = (k, v, r) => evicted.push([k, v, r]);
+  return { cache, evicted, setTime: (n: number) => (t = n) };
+}
+
+test('get refreshes recency', () => {
+  const { cache } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.get('a');
+  cache.set('c', 3);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('entry is live while now < set time + ttl', () => {
+  const { cache, setTime } = setup(5, 1000);
+  cache.set('a', 1);
+  setTime(999);
+  expect(cache.get('a')).toBe(1);
+  expect(cache.size).toBe(1);
+  setTime(1000);
+  expect(cache.size).toBe(0);
+  expect(cache.keys()).toEqual([]);
+});
+
+test('set gives a fresh ttl and evicts nothing for an overwrite', () => {
+  const { cache, evicted, setTime } = setup(5, 1000);
+  cache.set('a', 1);
+  setTime(900);
+  cache.set('a', 2);
+  setTime(1500);
+  expect(cache.get('a')).toBe(2);
+  expect(evicted).toEqual([]);
+});
+
+test('expired entries are removed before a live one is evicted', () => {
+  const { cache, evicted, setTime } = setup(2, 100);
+  cache.set('a', 1);
+  setTime(50);
+  cache.set('b', 2);
+  setTime(120);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('expired entry found by get or delete reports expired', () => {
+  const { cache, evicted, setTime } = setup(5, 100);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  setTime(100);
+  expect(cache.get('a')).toBeUndefined();
+  expect(cache.delete('b')).toBe(false);
+  expect(evicted).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+  ]);
+});
+
+test('delete of a live entry reports delete', () => {
+  const { cache, evicted } = setup(5, 1000);
+  cache.set('a', 1);
+  expect(cache.delete('a')).toBe(true);
+  expect(cache.delete('a')).toBe(false);
+  expect(evicted).toEqual([['a', 1, 'delete']]);
+});
+
+test('capacity eviction removes the least recently used live entry', () => {
+  const { cache, evicted } = setup(2, 1000);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['a', 1, 'capacity']]);
+});
