+  let total = 0;
+  for (const [, num, unit] of trimmed.matchAll(/(\d+(?:\.\d+)?)(ms|d|h|m|s)/g)) {
+    total += Number(num) * UNIT_MS[unit];
+  }
+  return Math.round(total);
