+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+  expect(evicted).toEqual(['b2:capacity']);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
